<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {api} from './api';import OppeText from './OppeText.vue';import OppeCode from './OppeCode.vue';
const courses=ref([]),courseId=ref(''),category=ref(''),search=ref(''),status=ref(''),questions=ref([]),question=ref(null),code=ref(''),results=ref(null),solution=ref(null),busy=ref(''),error=ref(''),notice=ref(''),tab=ref('question'),manager=ref(false),author=ref(null),jsonText=ref(''),preview=ref(null),overwrite=ref(false),validatedText=ref(''),runnerReady=ref(false),customInput=ref(''),showCustom=ref(false),resetConfirm=ref(false),split=ref(45),workspace=ref(null),courseForm=ref(false);
const newCourse=ref({slug:'',name:'',language:'python',categories:'OPPE1, OPPE2'});
const selectedCourse=computed(()=>courses.value.find(c=>c.id===Number(courseId.value)));
const filtered=computed(()=>questions.value.filter(q=>(!category.value||q.category===category.value)&&(!status.value||q.status===status.value)&&(!search.value||(q.title+' '+q.topic).toLowerCase().includes(search.value.toLowerCase()))));
const editorText=ref('');
const draftContent=computed(()=>{try{return JSON.parse(editorText.value)}catch{return null}});
function updateContent(key,value){if(!draftContent.value)return;editorText.value=JSON.stringify({...draftContent.value,[key]:value},null,2)}
function updateTest(index,key,value){const tests=draftContent.value.tests.map((t,i)=>i===index?{...t,[key]:value}:t);updateContent('tests',tests)}
function updateFixture(i,text){try{updateTest(i,'files',JSON.parse(text));error.value=''}catch{error.value='Starting files must be valid JSON'}}
function addTest(){updateContent('tests',[...draftContent.value.tests,{input:'',expected:'',hidden:true,files:{}}])}
function removeTest(index){updateContent('tests',draftContent.value.tests.filter((_,i)=>i!==index))}
async function action(label,fn){if(busy.value)return;busy.value=label;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=''}}
async function loadCourses(){const d=await api('/admin/oppe/courses');courses.value=d.items;runnerReady.value=d.runner_configured;if(!courseId.value&&d.items.length)courseId.value=d.items[0].id;await loadQuestions()}
async function loadQuestions(){question.value=null;author.value=null;category.value='';questions.value=(await api('/admin/oppe/questions?'+new URLSearchParams({course_id:courseId.value}))).items}
onMounted(()=>action('Loading courses',loadCourses));
async function open(q){await action('Opening question',async()=>{question.value=await api('/admin/oppe/questions/'+q.id);code.value=question.value.question.starter_code;solution.value=null;results.value=null;author.value=null;resetConfirm.value=false;tab.value='question';await nextTick();workspace.value?.scrollIntoView({block:'start',behavior:'smooth'})})}
async function execute(kind){await action(kind==='submit'?'Checking all tests':'Running code',async()=>{const d=await api('/admin/oppe/questions/'+question.value.id+'/execute',{method:'POST',body:{code:code.value,revision:question.value.revision,action:kind,input:customInput.value}});results.value=d;tab.value='results'})}
async function reveal(){await action('Loading explanation',async()=>{solution.value=await api('/admin/oppe/questions/'+question.value.id+'/solution');tab.value='question'})}
async function downloadTemplate(){await action('Preparing template',async()=>{const d=await api('/admin/oppe/template?'+new URLSearchParams({course_slug:selectedCourse.value?.slug||'python'}));jsonText.value=JSON.stringify(d,null,2);download('oppe-import-template.json',jsonText.value)})}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function readFile(e){const file=e.target.files?.[0];if(!file)return;if(file.size>3000000){error.value='JSON file must be under 3 MB';return}jsonText.value=await file.text();preview.value=null}
async function importBundle(save=false){await action(save?'Saving drafts':'Checking import',async()=>{if(save&&validatedText.value!==JSON.stringify([jsonText.value,overwrite.value]))throw Error('Preview this import again first.');const d=await api('/admin/oppe/import',{method:'POST',body:{bundle:JSON.parse(jsonText.value),overwrite:overwrite.value,save}});preview.value=d;if(save){notice.value=d.saved+' drafts saved. Validate each reference solution before marking ready.';validatedText.value='';await loadCourses()}else validatedText.value=JSON.stringify([jsonText.value,overwrite.value])})}
async function newQuestion(){await action('Preparing question',async()=>{if(!selectedCourse.value)throw Error('Select a course first');author.value={course_id:Number(courseId.value),external_id:'',content:{title:'',statement:'',topic:'',category:selectedCourse.value.categories[0],difficulty:'Medium',starter_code:'',prefix:'',suffix:'',reference_solution:'',explanation:'',source:'',setup_sql:'',time_limit:3,entrypoint:'Main',execution_mode:'stdin',entry_function:'',import_notes:[],tests:[{input:'',expected:'',hidden:false,files:{}},{input:'',expected:'',hidden:true,files:{}}]}};editorText.value=JSON.stringify(author.value.content,null,2)})}
async function editQuestion(){await action('Opening authoring',async()=>{author.value=await api('/admin/oppe/questions/'+question.value.id+'/author');editorText.value=JSON.stringify(author.value.content,null,2)})}
async function saveAuthor(){await action('Saving draft',async()=>{const a=author.value;const content=JSON.parse(editorText.value);author.value=await api('/admin/oppe/questions'+(a.id?'/'+a.id:''),{method:a.id?'PUT':'POST',body:{course_id:a.course_id,external_id:a.external_id,content,revision:a.revision}});editorText.value=JSON.stringify(author.value.content,null,2);question.value=null;notice.value='Draft saved. Validate reference code next.';questions.value=(await api('/admin/oppe/questions?course_id='+courseId.value)).items})}
const unsaved=computed(()=>author.value&&editorText.value!==JSON.stringify(author.value.content,null,2));
async function validateAuthor(){await action('Validating all test cases',async()=>{if(unsaved.value)throw Error('Save your changes first.');const r=await api('/admin/oppe/questions/'+author.value.id+'/validate',{method:'POST',body:{revision:author.value.revision}});results.value={...r,total:r.results.length,passed:r.results.filter(t=>t.passed).length};author.value=await api('/admin/oppe/questions/'+author.value.id+'/author');notice.value=r.passed?'Every test passed. Ready for admin preview.':'Validation failed. Review output and expected results.'})}
async function publishAuthor(){await action('Marking ready',async()=>{if(unsaved.value)throw Error('Save and validate changes first.');await api('/admin/oppe/questions/'+author.value.id+'/publish',{method:'POST',body:{revision:author.value.revision}});author.value.status='READY';notice.value='Ready — still visible to admins only.';questions.value=(await api('/admin/oppe/questions?course_id='+courseId.value)).items})}
async function addCourse(){await action('Adding course',async()=>{await api('/admin/oppe/courses',{method:'POST',body:{...newCourse.value,categories:newCourse.value.categories.split(',').map(x=>x.trim()).filter(Boolean)}});courseForm.value=false;await loadCourses()})}
function move(e){if(!workspace.value)return;const r=workspace.value.getBoundingClientRect();split.value=Math.min(70,Math.max(30,(e.clientX-r.left)/r.width*100))}
function drag(e){e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.addEventListener('pointermove',move);const target=e.currentTarget;target.onpointerup=()=>target.removeEventListener('pointermove',move);target.onlostpointercapture=()=>target.removeEventListener('pointermove',move)}
function dividerKey(e){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();split.value=Math.max(30,Math.min(70,split.value+(e.key==='ArrowRight'?2:-2)))}}
</script>
<template>
<section class="oppe-page">
 <a href="/" class="breadcrumb-link">← Paper library</a>
 <header class="oppe-heading"><div><div class="eyebrow">ADMIN PREVIEW · CODING WORKSPACE</div><h1>Practice OPPE<span class="oppe-dot">.</span></h1><p class="muted">Read. Build. Test. Understand.</p></div><button class="btn btn-outline-primary" @click="manager=!manager">{{manager?'Close management':'Manage questions'}}</button></header>
 <p class="oppe-private">🔒 Private preview. Every OPPE API requires an active admin account. “Ready” questions remain private.</p>
 <p v-if="!runnerReady" class="alert alert-warning">Execution runner is not connected. You can prepare questions and preview the editor. Run, validation and submission become available after runner setup.</p>
 <p v-if="error" role="alert" class="alert alert-danger">{{error}}</p><p v-if="notice" role="status" class="alert alert-success">{{notice}}</p><p v-if="busy" role="status" class="oppe-working"><span class="spinner-border spinner-border-sm"/> {{busy}}…</p>
 <div v-if="!courses.length&&!busy" class="panel"><h2>Set up your courses</h2><p>Python · DBMS · PDSA · Java · System Commands</p><button class="btn btn-primary" @click="action('Creating courses',async()=>{await api('/admin/oppe/courses/defaults',{method:'POST'});await loadCourses()})">Create the five courses</button></div>
 <div class="oppe-filters"><label>Course<select class="form-select" v-model="courseId" @change="action('Loading questions',loadQuestions)" :disabled="!!busy"><option v-for="c in courses" :key="c.id" :value="c.id">{{c.name}} · {{c.question_count}}</option></select></label><label>Exam<select class="form-select" v-model="category"><option value="">All exams</option><option v-for="c in selectedCourse?.categories" :key="c">{{c}}</option></select></label><label>Search<input class="form-control" v-model="search" placeholder="Title or concept…" type="search"></label><label>Status<select class="form-select" v-model="status"><option value="">All questions</option><option>DRAFT</option><option>READY</option></select></label></div>
 <section v-if="manager" class="panel oppe-manager"><div class="section-row"><h2>Content management</h2><div class="d-flex gap-2 flex-wrap"><button class="btn btn-primary" @click="newQuestion" :disabled="!!busy||!selectedCourse">Add question</button><button class="btn btn-light" @click="courseForm=!courseForm">Add course</button><button class="btn btn-light" @click="downloadTemplate" :disabled="!!busy">Import template</button></div></div>
 <form v-if="courseForm" @submit.prevent="addCourse" class="oppe-filters"><label>Name<input v-model="newCourse.name" class="form-control" required maxlength="100"></label><label>Slug<input v-model="newCourse.slug" class="form-control" required pattern="[a-z][a-z0-9-]*"></label><label>Runtime<select v-model="newCourse.language" class="form-select"><option>python</option><option>java</option><option>postgresql</option><option>shell</option></select></label><label>Exam categories<input v-model="newCourse.categories" class="form-control" required></label><button class="btn btn-primary" :disabled="!!busy">Save course</button></form>
 <details><summary>Import up to 50 questions as JSON</summary><p class="muted">Same external ID identifies the same question in a course. Overwrite resets validation and returns it to draft.</p><input type="file" accept=".json,application/json" @change="readFile" class="form-control mb-2"><textarea v-model="jsonText" class="form-control font-monospace" rows="8" aria-label="Question import JSON"/><label class="my-2 d-block"><input type="checkbox" v-model="overwrite"> Overwrite matching external IDs</label><div class="d-flex gap-2"><button class="btn btn-light" @click="importBundle(false)" :disabled="!!busy||!jsonText">Preview import</button><button class="btn btn-primary" @click="importBundle(true)" :disabled="!!busy||validatedText!==JSON.stringify([jsonText,overwrite])">Save imported drafts</button></div><ul v-if="preview"><li v-for="p in preview.items" :key="p.external_id">{{p.title}} · {{p.replacing?'replace':'new'}}</li></ul></details>
 </section>
 <section v-if="author" class="panel oppe-author"><h2>{{author.id?'Edit question #'+author.id:'New question'}}</h2><p class="muted">Write the question, starter code, reference solution and tests below. Save → Validate → Mark ready. Hidden tests and reference code are author-only.</p><label>External ID<input v-model="author.external_id" :disabled="!!author.id" class="form-control" maxlength="100"></label><div v-if="draftContent" class="oppe-author-fields">
 <div class="oppe-filters"><label>Title<input class="form-control" :value="draftContent.title" @input="updateContent('title',$event.target.value)" maxlength="180"></label><label>Topic<input class="form-control" :value="draftContent.topic" @input="updateContent('topic',$event.target.value)"></label><label>Exam<select class="form-select" :value="draftContent.category" @change="updateContent('category',$event.target.value)"><option v-for="c in selectedCourse?.categories" :key="c">{{c}}</option></select></label><label>Difficulty<select class="form-select" :value="draftContent.difficulty" @change="updateContent('difficulty',$event.target.value)"><option>Easy</option><option>Medium</option><option>Hard</option></select></label></div>
 <label v-for="[field,label,rows] in [['statement','Question statement',6],['starter_code','Starter code (editable area)',6],['prefix','Fixed prefix — optional',3],['suffix','Fixed suffix — optional',3],['reference_solution','Reference solution (editable area only)',8],['explanation','Stepwise explanation',6],['source','Source / paper / permission reference',2]]" :key="field" class="d-block my-3">{{label}}<textarea class="form-control font-monospace mt-1" :rows="rows" :value="draftContent[field]" @input="updateContent(field,$event.target.value)"/></label>
 <label v-if="selectedCourse?.language==='postgresql'" class="d-block my-3">SQL schema and seed data<textarea class="form-control font-monospace" rows="8" :value="draftContent.setup_sql" @input="updateContent('setup_sql',$event.target.value)"/></label>
 <label>Execution limit (seconds)<input type="number" min="1" max="10" class="form-control" :value="draftContent.time_limit" @input="updateContent('time_limit',Number($event.target.value))"></label>
 <label v-if="selectedCourse?.language==='java'" class="d-block my-3">Java entry class<input class="form-control" :value="draftContent.entrypoint||'Main'" @input="updateContent('entrypoint',$event.target.value)"></label>
 <div v-if="selectedCourse?.language==='python'" class="oppe-filters"><label>Execution mode<select class="form-select" :value="draftContent.execution_mode||'stdin'" @change="updateContent('execution_mode',$event.target.value)"><option value="stdin">Program / stdin</option><option value="python-call">Function with JSON arguments</option><option value="python-dispatch">Named function with JSON arguments</option></select></label><label v-if="['python-call','python-dispatch'].includes(draftContent.execution_mode)">Entry function<input class="form-control" :value="draftContent.entry_function" @input="updateContent('entry_function',$event.target.value)"></label><label v-if="draftContent.execution_mode==='python-dispatch'">Allowed functions (comma separated)<input class="form-control" :value="(draftContent.entry_functions||[]).join(', ')" @input="updateContent('entry_functions',$event.target.value.split(',').map(v=>v.trim()).filter(Boolean))"></label></div>
 <ul v-if="draftContent.import_notes?.length" class="alert alert-warning"><li v-for="note in draftContent.import_notes" :key="note">{{note}}</li></ul>
 <h3 class="mt-4">Test cases</h3><p class="muted">Drafts can be incomplete. Before validation, include at least one visible sample, one real hidden case and reference code. Expected output is compared exactly, except trailing newlines.</p>
 <section v-for="(t,i) in draftContent.tests" :key="i" class="oppe-sample"><div class="section-row"><strong>Test {{i+1}}</strong><label><input type="checkbox" :checked="t.hidden" @change="updateTest(i,'hidden',$event.target.checked)"> Hidden</label><button class="text-btn" @click="removeTest(i)">Remove</button></div><div class="oppe-io"><label>Input<textarea class="form-control font-monospace" rows="3" :value="t.input" @input="updateTest(i,'input',$event.target.value)"/></label><label>Expected output<textarea class="form-control font-monospace" rows="3" :value="t.expected" @input="updateTest(i,'expected',$event.target.value)"/></label></div><label v-if="selectedCourse?.language==='postgresql'" class="d-block mt-2">Override SQL schema/data for this test (optional)<textarea class="form-control font-monospace" rows="4" :value="t.setup_sql||''" @input="updateTest(i,'setup_sql',$event.target.value)"/></label><details><summary>Starting files (JSON path → text)</summary><textarea class="form-control font-monospace" rows="3" :value="JSON.stringify(t.files,null,2)" @change="updateFixture(i,$event.target.value)"/></details></section>
 <button class="btn btn-light mb-3" @click="addTest" :disabled="draftContent.tests.length>=20">Add test case</button>
 <details><summary>Statement and solution preview</summary><OppeText :text="draftContent.statement" inline-dollar/><hr><OppeText :text="draftContent.explanation" inline-dollar/></details></div>
 <details class="my-3"><summary>Advanced: edit complete JSON</summary><textarea v-model="editorText" class="form-control font-monospace my-3" rows="18" aria-label="Question authoring JSON"/></details><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary" @click="saveAuthor" :disabled="!!busy">Save draft</button><button class="btn btn-light" @click="validateAuthor" :disabled="!!busy||!author.id||unsaved||!runnerReady">Validate reference solution</button><button class="btn btn-outline-primary" @click="publishAuthor" :disabled="!!busy||!author.validated||unsaved">Mark ready for admin preview</button><button class="btn btn-light" @click="author=null">Close</button></div><div v-if="results"><p v-for="(r,i) in results.results" :key="i">Test {{i+1}} · {{r.passed?'Passed':'Failed'}} · {{r.status}}<pre v-if="!r.passed">{{r.error||r.output}}</pre></p></div></section>
 <div class="section-row mt-4"><h2>{{selectedCourse?.name||'Questions'}} <span class="muted">/ {{category||'All exams'}}</span></h2><span class="muted">{{filtered.length}} questions</span></div>
 <div class="oppe-question-list"><button v-for="(q,i) in filtered" :key="q.id" class="oppe-question-card" :class="{selected:question?.id===q.id}" @click="open(q)" :disabled="!!busy"><span class="oppe-number">{{String(i+1).padStart(2,'0')}}</span><span><strong>{{q.title}}</strong><small>{{q.category}} · {{q.topic||'General'}} · {{q.difficulty}}</small></span><span class="oppe-status">{{q.status==='READY'?'Ready':'Draft'}} →</span></button></div>
 <div v-if="!filtered.length&&!busy" class="panel empty"><h3>No questions here yet</h3><p>Use Manage questions to add your own or import an authorised question bundle.</p></div>
 <template v-if="question&&!author"><div class="oppe-work-heading"><div><span class="eyebrow">{{question.course.name}} · {{question.question.category}}</span><h2>{{question.question.title}}</h2></div><button class="btn btn-light" @click="editQuestion" :disabled="!!busy">Edit question</button></div>
 <nav class="oppe-mobile-tabs" aria-label="Practice panels"><button v-for="t in ['question','code','results']" :key="t" @click="tab=t" :class="{active:tab===t}">{{t}}</button></nav>
 <div ref="workspace" class="oppe-workspace" :style="{'--oppe-left':split+'%'}">
 <article class="oppe-statement panel" :class="{'mobile-visible':tab==='question'}"><div class="oppe-panel-label">PROBLEM <span>{{question.question.time_limit}}s execution limit</span></div><OppeText :text="question.question.statement" inline-dollar/><p v-if="question.question.source" class="muted small">Source: {{question.question.source}}</p><ul v-if="question.question.import_notes?.length" class="alert alert-warning"><li v-for="note in question.question.import_notes" :key="note">{{note}}</li></ul><p v-if="!question.submission_ready" class="muted small">Draft: hidden tests are not available yet. Samples can be run; final submission is disabled.</p><h3>Sample cases</h3><section v-for="(s,i) in question.question.samples" :key="i" class="oppe-sample"><strong>Sample {{i+1}}</strong><div class="oppe-io"><div><small>INPUT</small><pre>{{s.input||'(empty)'}}</pre></div><div><small>EXPECTED OUTPUT</small><pre>{{s.expected||'(empty)'}}</pre></div></div><details v-if="Object.keys(s.files).length"><summary>Starting files</summary><section v-for="(text,path) in s.files" :key="path"><strong>{{path}}</strong><pre>{{text}}</pre></section></details></section><button class="btn btn-light mt-3" @click="reveal" :disabled="!!busy">{{solution?'Reload solution':'Show solution'}}</button><section v-if="solution" class="oppe-solution"><h3>Approach & explanation</h3><OppeText :text="solution.explanation" inline-dollar/><pre>{{solution.code}}</pre></section></article>
 <div class="oppe-divider" role="separator" tabindex="0" aria-label="Resize question and editor panels" aria-orientation="vertical" :aria-valuenow="Math.round(split)" aria-valuemin="30" aria-valuemax="70" @pointerdown="drag" @keydown="dividerKey"><span>⋮</span></div>
 <section class="oppe-editor-panel panel" :class="{'mobile-visible':tab==='code'||tab==='results'}"><div class="oppe-panel-label">{{question.course.language}} <button class="text-btn" @click="resetConfirm=!resetConfirm">Reset code</button></div><p v-if="resetConfirm" class="oppe-reset">Replace your current code with the starter?<button @click="code=question.question.starter_code;resetConfirm=false" class="btn btn-sm btn-light">Reset</button><button @click="resetConfirm=false" class="text-btn">Cancel</button></p>
 <div class="oppe-code-area" :class="{'mobile-hidden':tab==='results'}"><details v-if="question.question.prefix"><summary>Fixed prefix (read only)</summary><pre>{{question.question.prefix}}</pre></details><OppeCode :key="question.id" v-model="code" :language="question.course.language"/><details v-if="question.question.suffix"><summary>Fixed suffix (read only)</summary><pre>{{question.question.suffix}}</pre></details></div>
 <div class="oppe-runbar"><button class="btn btn-light" @click="execute('run')" :disabled="!!busy||!runnerReady">▶ Run samples</button><button class="btn btn-primary" @click="execute('submit')" :disabled="!!busy||!runnerReady||!question.submission_ready">Submit all tests</button><button class="text-btn" @click="showCustom=!showCustom">Custom input</button></div><div v-if="showCustom" class="p-3"><textarea v-model="customInput" aria-label="Custom input" class="form-control font-monospace" rows="3" placeholder="stdin…"/><button @click="execute('custom')" :disabled="!!busy||!runnerReady" class="btn btn-light mt-2">Run custom input</button></div>
 <section v-if="results" class="oppe-results" :class="{'mobile-hidden':tab==='code'}" aria-live="polite"><h3>{{results.action==='custom'?'Custom output':results.passed+' / '+results.total+' tests passed'}}</h3><details v-for="(r,i) in results.results" :key="i" :open="!r.hidden&&!r.passed"><summary><span :class="r.passed?'oppe-pass':'oppe-fail'">{{r.hidden?'Hidden':'Sample'}} {{i+1}} · {{r.status}}</span></summary><template v-if="!r.hidden"><div class="oppe-io"><div><small>EXPECTED</small><pre>{{r.expected??'Not graded'}}</pre></div><div><small>ACTUAL</small><pre>{{r.output||'(empty)'}}</pre></div></div><pre v-if="r.error" class="oppe-fail">{{r.error}}</pre></template><p v-else>Hidden input and expected output are private.</p></details></section>
 </section></div></template>
</section>
</template>
<style>
.oppe-page{--oppe-code-bg:#f8fafc;--oppe-code-fg:#172033}.oppe-heading,.oppe-work-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0}.oppe-heading h1{font-size:clamp(28px,4vw,44px);letter-spacing:-1.5px}.oppe-dot{color:#6366f1}.oppe-private{border-left:3px solid #6366f1;padding:12px 16px;background:#6366f10c;font-size:13px}.oppe-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:22px 0}.oppe-filters label{font-size:12px;font-weight:600}.oppe-filters input,.oppe-filters select{margin-top:6px}.oppe-working{display:flex;gap:10px;align-items:center;color:#6366f1}.oppe-question-list{display:grid;gap:8px;max-height:380px;overflow:auto}.oppe-question-card{display:flex;gap:14px;align-items:center;width:100%;text-align:left;border:1px solid var(--line,#e2e8f0);border-radius:12px;padding:16px;background:var(--panel,#fff);color:inherit}.oppe-question-card:hover,.oppe-question-card.selected{border-color:#818cf8;background:#6366f108}.oppe-number{font-family:monospace;color:#94a3b8}.oppe-question-card small{display:block;color:#64748b;margin-top:6px}.oppe-status{margin-left:auto;font-size:12px;white-space:nowrap}.oppe-workspace{display:grid;grid-template-columns:minmax(0,var(--oppe-left)) 12px minmax(0,1fr);align-items:start;scroll-margin-top:20px}.oppe-workspace .panel{padding:0;min-width:0;overflow:hidden}.oppe-statement{max-height:85vh;overflow:auto!important;padding:22px!important}.oppe-panel-label{display:flex;justify-content:space-between;gap:10px;font:600 11px ui-monospace,monospace;text-transform:uppercase;letter-spacing:1px;margin-bottom:18px}.oppe-panel-label span{font-weight:400;letter-spacing:0}.oppe-editor-panel>.oppe-panel-label{padding:16px;margin:0;border-bottom:1px solid #94a3b833}.oppe-divider{display:flex;justify-content:center;align-items:center;min-height:400px;cursor:col-resize;touch-action:none;color:#94a3b8}.oppe-divider:focus,.oppe-divider:hover{background:#6366f120;color:#6366f1}.oppe-sample,.oppe-results details{padding:12px;border:1px solid #94a3b833;border-radius:8px;margin:10px 0}.oppe-io{display:grid;grid-template-columns:1fr 1fr;gap:10px}.oppe-io>div{min-width:0}.oppe-io small{font-size:10px;color:#64748b;letter-spacing:1px}.oppe-page pre{white-space:pre;overflow:auto;font-size:12px;background:#64748b0c;padding:12px;border-radius:6px;max-height:300px;tab-size:4}.oppe-code{height:400px;overflow:hidden}.oppe-code-area>details{padding:8px 14px;font-size:12px}.oppe-runbar{display:flex;flex-wrap:wrap;gap:8px;padding:14px;border-top:1px solid #94a3b833}.oppe-results{padding:16px;max-height:380px;overflow:auto}.oppe-results h3{font-size:16px}.oppe-pass{color:#15803d}.oppe-fail{color:#dc2626}.oppe-solution{margin-top:20px;border-top:1px solid #94a3b833;padding-top:20px}.oppe-reset{padding:12px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:12px}.oppe-mobile-tabs{display:none}.oppe-manager details>summary{cursor:pointer;padding:12px 0}.oppe-author textarea{font-size:12px;tab-size:2}
[data-theme=dark] .oppe-page{--oppe-code-bg:#111827;--oppe-code-fg:#e5e7eb}[data-theme=dark] .oppe-question-card{background:#172033;border-color:#334155}[data-theme=dark] .oppe-question-card small,[data-theme=dark] .oppe-io small{color:#94a3b8}[data-theme=dark] .oppe-pass{color:#86efac}[data-theme=dark] .oppe-fail{color:#fca5a5}
@media(max-width:900px){.oppe-filters{grid-template-columns:1fr 1fr}.oppe-workspace{display:block}.oppe-divider{display:none}.oppe-mobile-tabs{display:flex;gap:4px;margin:12px 0;background:#64748b12;border-radius:10px;padding:4px}.oppe-mobile-tabs button{flex:1;border:0;padding:10px;background:transparent;color:inherit;text-transform:capitalize;border-radius:8px}.oppe-mobile-tabs .active{background:#6366f1;color:white}.oppe-statement,.oppe-editor-panel{display:none}.oppe-workspace .mobile-visible{display:block;max-height:none}.oppe-editor-panel .mobile-hidden{display:none}.oppe-code{height:48vh;min-height:280px}.oppe-heading,.oppe-work-heading{align-items:flex-start}.oppe-heading h1{letter-spacing:-.7px}.oppe-status{display:none}.oppe-io{grid-template-columns:1fr}.oppe-statement{padding:16px!important}}
</style>
